        {...inputProps}
        id={inputId}
        className={['ui-text-field__input', className].filter(Boolean).join(' ')}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? errorId : undefined}
      />
      {error ? (
        <p id={errorId} role="alert" className="ui-text-field__error">
          {error}
        </p>
